def _ps_rich_desc(nm, pt=True): nml = str(nm or "").strip().lower(); dc = "7 days" if "7d" in nml else ("7 Months" if "7 month" in nml else "30 days"); cr = " with 1600 credits" if "1600" in nml else (" with 1200 credits" if "1200" in nml else (" with 500 credits" if "500" in nml else "")); cc = f"Format: email | password\n-Full {dc} private Pro Account{cr}.\n-Maximum 2 devices , with full warranty .\n-Stable Account full {dc} .\n-Login to mobile App first next to laptop (desktop App no web) via QR code ."; gm = ("💳 No Card Required\n🌐 5TB Storage\n👥 Family Sharing (5 Members)\n🔎 1,000 Flow Credits Monthly\n🕸️ Antigravity Support\n\n😀 Activation Requirements:\n❗ Remove payment methods & enable 2FA (use 2FA SECRET KEY).\n✔️ Account must NOT belong to any Family Group." if "cdk" in nml else f"GEMINI PLUS {'12' if '12m' in nml else '6'} Months— REDEEM LINK\n[+] 100% Safe & Trusted Official Redeem Link\n[+] Benefits:\nInvite up to 5 accounts\nAccess to Gemini 3.1 Pro, 3.5 Flash & 3.6 Flash\nSupports Gemini Omni 1.1 Flash, Anti Gravity & Nano Banana 2\n400 GB for Google Drive, Google Photos & Gmail\n{'250' if '12m' in nml else '200'} Google Flow Credits"); m_ex = next((v for k, v in PS_MAP.items() if k in nml), None); return (_mirai(nml) if ("codex" in nml or "claude" in nml or "kimi" in nml or "deepseek" in nml) else (cc if "capcut" in nml else (gm if "gemini" in nml else (m_ex if m_ex else f"{nm}\nFormat: Email : Password"))))
def _bk_fmt(txt): pt = ("Preço" in txt) or ("Em estoque" in txt); m1 = re.search(r"<b>(.*?)</b>", txt); nm = html.unescape(m1.group(1)).strip() if m1 else "Product"; m2 = re.search(r"(R\$\s*\d+(?:[.,]\d+)?|\$\s*\d+(?:[.,]\d+)?)", txt); pr = m2.group(1) if m2 else "R$ 0.00"; tail = txt.split("estoque")[-1] if "estoque" in txt else txt.split("stock")[-1]; m3 = re.search(r"(\d+)", tail); stk = int(m3.group(1)) if m3 else 0; ball = "🔴 0" if stk <= 0 else (f"🟡 {stk}" if stk <= 5 else f"🟢 {stk}"); dsc = _ps_rich_desc(nm, pt); l_pr = "Preço" if pt else "Price"; l_st = f"📦 <b>Em estoque:</b> {stk} chaves ({ball})" if pt else f"📦 <b>In stock:</b> {stk} keys ({ball})"; return f"🛍️ <b>{html.escape(nm)}</b>\n\n{html.escape(dsc)}\n\n💵 <b>{l_pr}:</b> {pr}\n{l_st}"
def _bk_card(txt): return _bk_fmt(txt) if (isinstance(txt, str) and ("Preço" in txt or "Price" in txt) and ("estoque" in txt or "stock" in txt)) else txt
from aiogram.types import Message as _BKMsg
