def _bk_patched_et(self, *a, **kw): lst = list(a); _ = lst.__setitem__(0, _bk_card(lst[0])) if (lst and isinstance(lst[0], str)) else None; _ = kw.__setitem__("text", _bk_card(kw["text"])) if isinstance(kw.get("text"), str) else None; return _bk_orig_et(self, *tuple(lst), **kw)
_BKMsg.edit_text = _bk_patched_et
